// Crypto test harness — verifies the dependency-free SHA-256/HMAC/HKDF,
// X25519, AES-256-GCM and AES-256-CBC implementations against vectors
// generated by Node's crypto module (incl. the RFC 7748 X25519 vector).
//
// Build & run (no Qt required):
//   g++ -std=c++17 -I qt/src/direct qt/tests/test_crypto.cpp
//       qt/src/direct/sha256.cpp qt/src/direct/x25519.cpp
//       qt/src/direct/aes_gcm.cpp -o /tmp/test_crypto
//   /tmp/test_crypto qt/tests/crypto_vectors.txt

#include "sha256.h"
#include "x25519.h"
#include "aes_gcm.h"

#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

using namespace wa::crypto;

namespace {

Bytes hex(const std::string &h) {
    if (h == "-") return Bytes();
    return fromHex(h);
}

int pass = 0, fail = 0;

void check(bool ok, const char *what, const std::string &detail = "") {
    if (ok) { pass++; return; }
    fail++;
    std::fprintf(stderr, "FAIL %s %s\n", what, detail.c_str());
}

} // namespace

int main(int argc, char **argv) {
    const std::string path = argc > 1 ? argv[1] : "qt/tests/crypto_vectors.txt";
    std::ifstream in(path);
    if (!in) { std::fprintf(stderr, "cannot open %s\n", path.c_str()); return 2; }

    std::string line;
    int sha = 0, hmac = 0, hkdfN = 0, x = 0, xb = 0, gcmN = 0, cbc = 0;

    while (std::getline(in, line)) {
        if (line.empty()) continue;
        std::istringstream ss(line);
        std::string kind;
        ss >> kind;

        if (kind == "SHA") {
            std::string msgHex, want;
            ss >> msgHex >> want;
            check(toHex(sha256(hex(msgHex))) == want, "SHA-256", msgHex.substr(0, 16));
            sha++;
        } else if (kind == "HMAC") {
            std::string keyHex, msgHex, want;
            ss >> keyHex >> msgHex >> want;
            check(toHex(hmacSha256(hex(keyHex), hex(msgHex))) == want, "HMAC-SHA256");
            hmac++;
        } else if (kind == "HKDF") {
            std::string ikmHex, saltHex, infoHex, want;
            ss >> ikmHex >> saltHex >> infoHex >> want;
            const Bytes out = hkdfSha256(hex(ikmHex), want.size() / 2, hex(saltHex), hex(infoHex));
            check(toHex(out) == want, "HKDF-SHA256");
            hkdfN++;
        } else if (kind == "X25519") {
            std::string privHex, pubHex, want;
            ss >> privHex >> pubHex >> want;
            const Bytes priv = hex(privHex), pub = hex(pubHex);
            uint8_t shared[32];
            check(x25519(priv.data(), pub.data(), shared) &&
                      toHex(Bytes(shared, shared + 32)) == want,
                  "X25519 shared secret");
            x++;
        } else if (kind == "XBASE") {
            std::string privHex, want;
            ss >> privHex >> want;
            const Bytes priv = hex(privHex);
            uint8_t pub[32];
            check(x25519Base(priv.data(), pub) &&
                      toHex(Bytes(pub, pub + 32)) == want,
                  "X25519 public key");
            xb++;
        } else if (kind == "GCM") {
            std::string keyHex, ivHex, aadHex, ptHex, want;
            ss >> keyHex >> ivHex >> aadHex >> ptHex >> want;
            const Bytes key = hex(keyHex), iv = hex(ivHex), aad = hex(aadHex), pt = hex(ptHex);
            const Bytes ct = aes256GcmEncrypt(pt, key, iv, aad);
            check(toHex(ct) == want, "AES-256-GCM encrypt");
            Bytes roundTrip;
            check(aes256GcmDecrypt(ct, key, iv, aad, roundTrip) && roundTrip == pt,
                  "AES-256-GCM decrypt");
            // Tampered tag must be rejected.
            Bytes bad = ct;
            bad[bad.size() - 1] ^= 0x01;
            Bytes ignored;
            check(!aes256GcmDecrypt(bad, key, iv, aad, ignored), "AES-256-GCM tamper rejection");
            gcmN++;
        } else if (kind == "CBC") {
            std::string keyHex, ivHex, ptHex, want;
            ss >> keyHex >> ivHex >> ptHex >> want;
            const Bytes key = hex(keyHex), iv = hex(ivHex), pt = hex(ptHex);
            const Bytes ct = aes256CbcEncrypt(pt, key, iv);
            check(toHex(ct) == want, "AES-256-CBC encrypt");
            Bytes rt;
            check(aes256CbcDecrypt(ct, key, iv, rt) && rt == pt, "AES-256-CBC decrypt");
            cbc++;
        }
    }

    std::printf("\n=== dependency-free crypto ===\n");
    std::printf("SHA-256          : %d vectors\n", sha);
    std::printf("HMAC-SHA256      : %d vectors\n", hmac);
    std::printf("HKDF-SHA256      : %d vectors\n", hkdfN);
    std::printf("X25519 shared    : %d vectors\n", x);
    std::printf("X25519 basepoint : %d vectors\n", xb);
    std::printf("AES-256-GCM      : %d vectors (+decrypt, +tamper)\n", gcmN);
    std::printf("AES-256-CBC      : %d vectors (+decrypt)\n", cbc);
    std::printf("\n%d passed, %d failed\n", pass, fail);
    std::printf("%s\n", fail == 0 ? "ALL CRYPTO TESTS PASSED" : "CRYPTO TESTS FAILED");
    return fail == 0 ? 0 : 1;
}
